// Kiro - a tiny UTF-8 text editor
// Reimplemented from behavioral observation.

mod cli;
mod term;
mod editor;
mod highlight;

use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    match cli::parse(&args) {
        cli::Action::PrintHelp => {
            print!("{}", cli::help_text(&args[0]));
            ExitCode::SUCCESS
        }
        cli::Action::PrintVersion => {
            println!("{}", env!("CARGO_PKG_VERSION"));
            ExitCode::SUCCESS
        }
        cli::Action::Run(files) => {
            match editor::run(&files) {
                Ok(()) => ExitCode::SUCCESS,
                Err(e) => {
                    eprintln!("Error: {}", e);
                    ExitCode::from(1)
                }
            }
        }
        cli::Action::Err(msg) => {
            eprintln!("Error: {}", msg);
            ExitCode::from(1)
        }
    }
}
