// Command-line argument parsing.

pub enum Action {
    PrintHelp,
    PrintVersion,
    Run(Vec<String>),
    Err(String),
}

pub fn help_text(prog: &str) -> String {
    let mut s = String::new();
    s.push_str(prog);
    s.push_str(": A tiny UTF-8 terminal text editor\n\n");
    s.push_str("Kiro is a tiny UTF-8 text editor on terminals for Unix-like systems.\n");
    s.push_str("Specify file paths to edit as a command argument or run without argument to\n");
    s.push_str("start to write a new text.\n");
    s.push_str("Help can show up with key mapping Ctrl-?.\n\n");
    s.push_str("Usage:\n");
    s.push_str("    ");
    s.push_str(prog);
    s.push_str(" [options] [FILES...]\n\n");
    s.push_str("Mappings:\n");
    s.push_str("    Ctrl-Q                        : Quit\n");
    s.push_str("    Ctrl-S                        : Save to file\n");
    s.push_str("    Ctrl-O                        : Open text buffer\n");
    s.push_str("    Ctrl-X                        : Next text buffer\n");
    s.push_str("    Alt-X                         : Previous text buffer\n");
    s.push_str("    Ctrl-P or UP                  : Move cursor up\n");
    s.push_str("    Ctrl-N or DOWN                : Move cursor down\n");
    s.push_str("    Ctrl-F or RIGHT               : Move cursor right\n");
    s.push_str("    Ctrl-B or LEFT                : Move cursor left\n");
    s.push_str("    Ctrl-A or Alt-LEFT or HOME    : Move cursor to head of line\n");
    s.push_str("    Ctrl-E or Alt-RIGHT or END    : Move cursor to end of line\n");
    s.push_str("    Ctrl-[ or Ctrl-V or PAGE DOWN : Next page\n");
    s.push_str("    Ctrl-] or Alt-V or PAGE UP    : Previous page\n");
    s.push_str("    Alt-F or Ctrl-RIGHT           : Move cursor to next word\n");
    s.push_str("    Alt-B or Ctrl-LEFT            : Move cursor to previous word\n");
    s.push_str("    Alt-N or Ctrl-DOWN            : Move cursor to next paragraph\n");
    s.push_str("    Alt-P or Ctrl-UP              : Move cursor to previous paragraph\n");
    s.push_str("    Alt-<                         : Move cursor to top of file\n");
    s.push_str("    Alt->                         : Move cursor to bottom of file\n");
    s.push_str("    Ctrl-H or BACKSPACE           : Delete character\n");
    s.push_str("    Ctrl-D or DELETE              : Delete next character\n");
    s.push_str("    Ctrl-W                        : Delete a word\n");
    s.push_str("    Ctrl-J                        : Delete until head of line\n");
    s.push_str("    Ctrl-K                        : Delete until end of line\n");
    s.push_str("    Ctrl-U                        : Undo last change\n");
    s.push_str("    Ctrl-R                        : Redo last undo change\n");
    s.push_str("    Ctrl-G                        : Search text\n");
    s.push_str("    Ctrl-M                        : New line\n");
    s.push_str("    Ctrl-L                        : Refresh screen\n");
    s.push_str("    Ctrl-?                        : Show this help\n\n");
    s.push_str("Options:\n");
    s.push_str("    -v, --version       Print version\n");
    s.push_str("    -h, --help          Print this help\n\n");
    s
}

/// Parse argv[1..]. Returns an Action. Mirrors the getopts-based parsing
/// used by the original program: version flag takes priority over help,
/// and unknown options produce "Unrecognized option: '<name>'." errors.
pub fn parse(argv: &[String]) -> Action {
    let mut help = false;
    let mut version = false;
    let mut free: Vec<String> = Vec::new();
    let mut i = 1;
    let mut after_double_dash = false;
    while i < argv.len() {
        let a = &argv[i];
        if after_double_dash {
            free.push(a.clone());
            i += 1;
            continue;
        }
        if a == "--" {
            after_double_dash = true;
            i += 1;
            continue;
        }
        if let Some(rest) = a.strip_prefix("--") {
            // long option
            let (name, _value) = match rest.find('=') {
                Some(pos) => (&rest[..pos], Some(&rest[pos + 1..])),
                None => (rest, None),
            };
            match name {
                "help" => help = true,
                "version" => version = true,
                other => {
                    return Action::Err(format!(
                        "Unrecognized option: '{}'. Please see --help for more details",
                        other
                    ));
                }
            }
            i += 1;
        } else if a.starts_with('-') && a.len() > 1 {
            // short options: process each char after '-'
            let chars: Vec<char> = a.chars().skip(1).collect();
            for c in chars {
                match c {
                    'h' => help = true,
                    'v' => version = true,
                    other => {
                        return Action::Err(format!(
                            "Unrecognized option: '{}'. Please see --help for more details",
                            other
                        ));
                    }
                }
            }
            i += 1;
        } else {
            free.push(a.clone());
            i += 1;
        }
    }

    // Priority: version flag takes precedence over help.
    if version {
        Action::PrintVersion
    } else if help {
        Action::PrintHelp
    } else {
        Action::Run(free)
    }
}
