// Editor core.

use std::fs;
use std::io::{self, Write};
use std::path::Path;

use crate::highlight;
use crate::term::{self, Key, KeyReader, RawMode};

const VERSION: &str = env!("CARGO_PKG_VERSION");
const TAB_STOP: usize = 4;

pub fn run(files: &[String]) -> io::Result<()> {
    // Ensure stdin is a terminal (best effort via ioctl TIOCGWINSZ)
    let (rows, cols) = term::get_winsize()?;
    let _raw = RawMode::enter()?;
    let mut editor = Editor::new(rows as usize, cols as usize);
    if files.is_empty() {
        editor.buffers.push(Buffer::empty());
    } else {
        for f in files {
            editor.buffers.push(Buffer::open(f)?);
        }
    }
    editor.draw()?;
    let mut reader = KeyReader::new();
    let mut quit_confirm = false;
    loop {
        if let Some(key) = reader.next()? {
            let result = editor.handle_key(key, &mut quit_confirm);
            match result {
                Action::Continue => {}
                Action::Quit => break,
            }
        }
        // Poll for terminal resize occasionally
        if let Ok((r, c)) = term::get_winsize() {
            let (r, c) = (r as usize, c as usize);
            if r != editor.rows || c != editor.cols {
                editor.rows = r;
                editor.cols = c;
            }
        }
        editor.draw()?;
    }
    Ok(())
}

pub enum Action {
    Continue,
    Quit,
}

pub struct Buffer {
    pub lines: Vec<String>,
    pub filename: Option<String>,
    pub modified: bool,
    pub cx: usize,  // cursor column (char index within line)
    pub cy: usize,  // cursor row (0-based line index)
    pub rowoff: usize,
    pub coloff: usize,
    pub lang: &'static str,
}

impl Buffer {
    pub fn empty() -> Self {
        Buffer {
            lines: vec![String::new()],
            filename: None,
            modified: false,
            cx: 0,
            cy: 0,
            rowoff: 0,
            coloff: 0,
            lang: "plain",
        }
    }

    pub fn open(path: &str) -> io::Result<Self> {
        let mut buf = Buffer::empty();
        buf.filename = Some(path.to_string());
        buf.lang = highlight::detect_language(path);
        match fs::read_to_string(path) {
            Ok(s) => {
                buf.lines = if s.is_empty() {
                    vec![String::new()]
                } else {
                    let mut v: Vec<String> =
                        s.split('\n').map(|l| l.trim_end_matches('\r').to_string()).collect();
                    // Trim trailing empty line introduced by terminal newline
                    if v.last().map(|l| l.is_empty()).unwrap_or(false) && v.len() > 1 {
                        v.pop();
                    }
                    v
                };
            }
            Err(e) => {
                if e.kind() != io::ErrorKind::NotFound {
                    return Err(e);
                }
                // New file — keep empty buffer
            }
        }
        Ok(buf)
    }

    pub fn save(&mut self) -> io::Result<usize> {
        let path = match &self.filename {
            Some(p) => p.clone(),
            None => {
                return Err(io::Error::new(io::ErrorKind::Other, "no filename"));
            }
        };
        let mut contents = self.lines.join("\n");
        contents.push('\n');
        let bytes = contents.as_bytes();
        fs::write(&path, bytes)?;
        self.modified = false;
        Ok(bytes.len())
    }

    fn line_len(&self, row: usize) -> usize {
        self.lines.get(row).map(|l| l.chars().count()).unwrap_or(0)
    }

    fn insert_char(&mut self, c: char) {
        if self.cy >= self.lines.len() {
            self.lines.push(String::new());
        }
        let line = &mut self.lines[self.cy];
        let byte_idx = char_index_to_byte(line, self.cx);
        line.insert(byte_idx, c);
        self.cx += 1;
        self.modified = true;
    }

    fn insert_newline(&mut self) {
        if self.cy >= self.lines.len() {
            self.lines.push(String::new());
        }
        let byte_idx = char_index_to_byte(&self.lines[self.cy], self.cx);
        let rest = self.lines[self.cy].split_off(byte_idx);
        self.lines.insert(self.cy + 1, rest);
        self.cy += 1;
        self.cx = 0;
        self.modified = true;
    }

    fn backspace(&mut self) {
        if self.cx > 0 {
            let byte_idx_end = char_index_to_byte(&self.lines[self.cy], self.cx);
            let byte_idx_start = char_index_to_byte(&self.lines[self.cy], self.cx - 1);
            self.lines[self.cy].replace_range(byte_idx_start..byte_idx_end, "");
            self.cx -= 1;
            self.modified = true;
        } else if self.cy > 0 {
            let prev_len = self.line_len(self.cy - 1);
            let cur = self.lines.remove(self.cy);
            self.cy -= 1;
            self.cx = prev_len;
            self.lines[self.cy].push_str(&cur);
            self.modified = true;
        }
    }

    fn delete_forward(&mut self) {
        let llen = self.line_len(self.cy);
        if self.cx < llen {
            let bs = char_index_to_byte(&self.lines[self.cy], self.cx);
            let be = char_index_to_byte(&self.lines[self.cy], self.cx + 1);
            self.lines[self.cy].replace_range(bs..be, "");
            self.modified = true;
        } else if self.cy + 1 < self.lines.len() {
            let next = self.lines.remove(self.cy + 1);
            self.lines[self.cy].push_str(&next);
            self.modified = true;
        }
    }

    fn delete_to_end(&mut self) {
        let llen = self.line_len(self.cy);
        if self.cx < llen {
            let bs = char_index_to_byte(&self.lines[self.cy], self.cx);
            self.lines[self.cy].truncate(bs);
            self.modified = true;
        } else if self.cy + 1 < self.lines.len() {
            let next = self.lines.remove(self.cy + 1);
            self.lines[self.cy].push_str(&next);
            self.modified = true;
        }
    }

    fn delete_to_head(&mut self) {
        if self.cx > 0 {
            let be = char_index_to_byte(&self.lines[self.cy], self.cx);
            self.lines[self.cy].replace_range(0..be, "");
            self.cx = 0;
            self.modified = true;
        } else if self.cy > 0 {
            let prev_len = self.line_len(self.cy - 1);
            let cur = self.lines.remove(self.cy);
            self.cy -= 1;
            self.cx = prev_len;
            self.lines[self.cy].push_str(&cur);
            self.modified = true;
        }
    }

    fn delete_word(&mut self) {
        // delete word before cursor
        if self.cx == 0 {
            self.backspace();
            return;
        }
        let line = &self.lines[self.cy];
        let chars: Vec<char> = line.chars().collect();
        let mut i = self.cx;
        while i > 0 && chars[i - 1].is_whitespace() {
            i -= 1;
        }
        while i > 0 && !chars[i - 1].is_whitespace() {
            i -= 1;
        }
        let bs = char_index_to_byte(line, i);
        let be = char_index_to_byte(line, self.cx);
        self.lines[self.cy].replace_range(bs..be, "");
        self.cx = i;
        self.modified = true;
    }
}

fn char_index_to_byte(s: &str, char_idx: usize) -> usize {
    s.char_indices().nth(char_idx).map(|(b, _)| b).unwrap_or(s.len())
}

pub struct Editor {
    pub rows: usize,
    pub cols: usize,
    pub buffers: Vec<Buffer>,
    pub current: usize,
    pub message: String,
    pub message_is_default: bool,
}

impl Editor {
    pub fn new(rows: usize, cols: usize) -> Self {
        Editor {
            rows,
            cols,
            buffers: Vec::new(),
            current: 0,
            message: "Ctrl-? for help".to_string(),
            message_is_default: true,
        }
    }

    pub fn buf(&self) -> &Buffer {
        &self.buffers[self.current]
    }
    pub fn buf_mut(&mut self) -> &mut Buffer {
        &mut self.buffers[self.current]
    }

    pub fn handle_key(&mut self, key: Key, quit_confirm: &mut bool) -> Action {
        // Reset one-shot message after a key (except if we just set it).
        // Actual redraw happens later.
        let is_quit = matches!(key, Key::Ctrl('q'));
        if !is_quit {
            *quit_confirm = false;
        }

        match key {
            Key::Ctrl('q') => {
                let any_modified = self.buffers.iter().any(|b| b.modified);
                if any_modified && !*quit_confirm {
                    self.message =
                        "At least one file has unsaved changes! Press ^Q again to quit or ^S to save"
                            .to_string();
                    self.message_is_default = false;
                    *quit_confirm = true;
                    return Action::Continue;
                }
                return Action::Quit;
            }
            Key::Ctrl('s') => {
                if self.buf().filename.is_none() {
                    // In the original, ^S prompts for filename; simplified here.
                    self.set_message("Ctrl-? for help".to_string());
                } else {
                    match self.buf_mut().save() {
                        Ok(n) => {
                            let p = self.buf().filename.clone().unwrap_or_default();
                            self.set_message(format!("{} bytes written to {}", n, p));
                        }
                        Err(e) => self.set_message(format!("Can't save: {}", e)),
                    }
                }
            }
            Key::Ctrl('x') => {
                if self.buffers.len() > 1 {
                    self.current = (self.current + 1) % self.buffers.len();
                }
            }
            Key::Alt('x') => {
                if self.buffers.len() > 1 {
                    self.current =
                        (self.current + self.buffers.len() - 1) % self.buffers.len();
                }
            }
            Key::Ctrl('p') | Key::Up => self.move_up(),
            Key::Ctrl('n') | Key::Down => self.move_down(),
            Key::Ctrl('b') | Key::Left => self.move_left(),
            Key::Ctrl('f') | Key::Right => self.move_right(),
            Key::Ctrl('a') | Key::Home | Key::AltLeft => self.buf_mut().cx = 0,
            Key::Ctrl('e') | Key::End | Key::AltRight => {
                let l = self.buf().line_len(self.buf().cy);
                self.buf_mut().cx = l;
            }
            Key::Ctrl('v') | Key::PageDown => self.page_down(),
            Key::Alt('v') | Key::PageUp => self.page_up(),
            Key::Ctrl(']') => self.page_up(),
            Key::Ctrl('[') => self.page_down(),
            Key::Alt('f') | Key::CtrlRight => self.move_next_word(),
            Key::Alt('b') | Key::CtrlLeft => self.move_prev_word(),
            Key::Alt('n') | Key::CtrlDown => self.move_next_paragraph(),
            Key::Alt('p') | Key::CtrlUp => self.move_prev_paragraph(),
            Key::Alt('<') => {
                self.buf_mut().cy = 0;
                self.buf_mut().cx = 0;
            }
            Key::Alt('>') => {
                let last = self.buf().lines.len().saturating_sub(1);
                self.buf_mut().cy = last;
                let l = self.buf().line_len(last);
                self.buf_mut().cx = l;
            }
            Key::Backspace | Key::Ctrl('h') => self.buf_mut().backspace(),
            Key::Delete | Key::Ctrl('d') => self.buf_mut().delete_forward(),
            Key::Ctrl('w') => self.buf_mut().delete_word(),
            Key::Ctrl('j') => self.buf_mut().delete_to_head(),
            Key::Ctrl('k') => self.buf_mut().delete_to_end(),
            Key::Ctrl('m') | Key::Enter => self.buf_mut().insert_newline(),
            Key::Ctrl('l') => { /* refresh */ }
            Key::Char(c) => self.buf_mut().insert_char(c),
            Key::Ctrl('?') => {
                // toggled help overlay not implemented; leave blank
            }
            _ => {}
        }
        Action::Continue
    }

    fn move_up(&mut self) {
        let b = self.buf_mut();
        if b.cy > 0 {
            b.cy -= 1;
            let l = b.line_len(b.cy);
            if b.cx > l {
                b.cx = l;
            }
        }
    }
    fn move_down(&mut self) {
        let b = self.buf_mut();
        if b.cy + 1 < b.lines.len() {
            b.cy += 1;
            let l = b.line_len(b.cy);
            if b.cx > l {
                b.cx = l;
            }
        }
    }
    fn move_left(&mut self) {
        let b = self.buf_mut();
        if b.cx > 0 {
            b.cx -= 1;
        } else if b.cy > 0 {
            b.cy -= 1;
            b.cx = b.line_len(b.cy);
        }
    }
    fn move_right(&mut self) {
        let l = self.buf().line_len(self.buf().cy);
        let b = self.buf_mut();
        if b.cx < l {
            b.cx += 1;
        } else if b.cy + 1 < b.lines.len() {
            b.cy += 1;
            b.cx = 0;
        }
    }
    fn page_down(&mut self) {
        let rows = self.rows.saturating_sub(2);
        let b = self.buf_mut();
        b.cy = (b.cy + rows).min(b.lines.len().saturating_sub(1));
        let l = b.line_len(b.cy);
        if b.cx > l {
            b.cx = l;
        }
    }
    fn page_up(&mut self) {
        let rows = self.rows.saturating_sub(2);
        let b = self.buf_mut();
        b.cy = b.cy.saturating_sub(rows);
        let l = b.line_len(b.cy);
        if b.cx > l {
            b.cx = l;
        }
    }
    fn move_next_word(&mut self) {
        let b = self.buf_mut();
        let line = b.lines[b.cy].clone();
        let chars: Vec<char> = line.chars().collect();
        let mut i = b.cx;
        while i < chars.len() && !chars[i].is_alphanumeric() {
            i += 1;
        }
        while i < chars.len() && chars[i].is_alphanumeric() {
            i += 1;
        }
        b.cx = i;
    }
    fn move_prev_word(&mut self) {
        let b = self.buf_mut();
        let line = b.lines[b.cy].clone();
        let chars: Vec<char> = line.chars().collect();
        let mut i = b.cx;
        if i > chars.len() {
            i = chars.len();
        }
        while i > 0 && !chars[i - 1].is_alphanumeric() {
            i -= 1;
        }
        while i > 0 && chars[i - 1].is_alphanumeric() {
            i -= 1;
        }
        b.cx = i;
    }
    fn move_next_paragraph(&mut self) {
        let b = self.buf_mut();
        let mut y = b.cy;
        while y + 1 < b.lines.len() && !b.lines[y].is_empty() {
            y += 1;
        }
        while y + 1 < b.lines.len() && b.lines[y].is_empty() {
            y += 1;
        }
        b.cy = y;
        let l = b.line_len(b.cy);
        if b.cx > l {
            b.cx = l;
        }
    }
    fn move_prev_paragraph(&mut self) {
        let b = self.buf_mut();
        let mut y = b.cy;
        while y > 0 && b.lines[y].is_empty() {
            y -= 1;
        }
        while y > 0 && !b.lines[y].is_empty() {
            y -= 1;
        }
        b.cy = y;
        let l = b.line_len(b.cy);
        if b.cx > l {
            b.cx = l;
        }
    }

    fn set_message(&mut self, m: String) {
        self.message = m;
        self.message_is_default = false;
    }

    pub fn draw(&mut self) -> io::Result<()> {
        self.scroll();
        let mut out = String::new();
        out.push_str("\x1b[?25l"); // hide cursor
        out.push_str("\x1b[H"); // home
        let text_rows = self.rows.saturating_sub(2);
        let show_welcome = self.buffers.len() == 1
            && !self.buf().modified
            && self.buf().filename.is_none()
            && self.buf().lines.len() == 1
            && self.buf().lines[0].is_empty();
        for screen_y in 0..text_rows {
            let file_y = self.buf().rowoff + screen_y;
            if file_y < self.buf().lines.len() {
                let line = &self.buf().lines[file_y];
                // Render taking coloff into account; simplified: no tabs expansion.
                let rendered = render_line(line);
                let visible: String = rendered
                    .chars()
                    .skip(self.buf().coloff)
                    .take(self.cols)
                    .collect();
                out.push_str(&visible);
            } else if show_welcome && screen_y == text_rows / 3 {
                let welcome = format!("Kiro editor -- version {}", VERSION);
                let pad = self.cols.saturating_sub(welcome.chars().count()) / 2;
                if pad > 0 {
                    out.push('~');
                    for _ in 0..pad.saturating_sub(1) {
                        out.push(' ');
                    }
                }
                out.push_str(&welcome);
            } else {
                out.push('~');
            }
            out.push_str("\x1b[K");
            out.push_str("\r\n");
        }
        // Status bar
        let fname = self
            .buf()
            .filename
            .clone()
            .unwrap_or_else(|| "[No Name]".to_string());
        let modified = if self.buf().modified { " (modified)" } else { "" };
        let left = format!(
            "\"{}\" - {}/{}{}",
            fname,
            self.current + 1,
            self.buffers.len(),
            modified,
        );
        let right = format!(
            "{} {}/{}",
            self.buf().lang,
            self.buf().cy + 1,
            self.buf().lines.len()
        );
        let left_len = left.chars().count();
        let right_len = right.chars().count();
        let total_visible = left_len + right_len;
        let pad = if total_visible < self.cols {
            self.cols - total_visible
        } else {
            0
        };
        out.push_str("\x1b[7m");
        out.push_str(&left);
        for _ in 0..pad {
            out.push(' ');
        }
        out.push_str(&right);
        // if too long, just let it wrap; simplified
        out.push_str("\x1b[m");
        out.push_str("\r\n");
        // Message line
        out.push_str("\x1b[K");
        let msg: String = self.message.chars().take(self.cols).collect();
        out.push_str(&msg);

        // Cursor position
        let cursor_row = (self.buf().cy - self.buf().rowoff) + 1;
        let cursor_col = (self.buf().cx - self.buf().coloff) + 1;
        out.push_str(&format!("\x1b[{};{}H", cursor_row, cursor_col));
        out.push_str("\x1b[?25h");

        let stdout = io::stdout();
        let mut h = stdout.lock();
        h.write_all(out.as_bytes())?;
        h.flush()?;
        Ok(())
    }

    fn scroll(&mut self) {
        let text_rows = self.rows.saturating_sub(2);
        let b = self.buf_mut();
        if b.cy < b.rowoff {
            b.rowoff = b.cy;
        }
        if b.cy >= b.rowoff + text_rows {
            b.rowoff = b.cy - text_rows + 1;
        }
        if b.cx < b.coloff {
            b.coloff = b.cx;
        }
        // Use raw cx since render_line doesn't expand widths
        if b.cx >= b.coloff + Self_cols(self) {
            b.coloff = b.cx - Self_cols(self) + 1;
        }
    }
}

fn Self_cols(e: &Editor) -> usize {
    e.cols
}

fn render_line(s: &str) -> String {
    // Expand tabs to TAB_STOP spaces (simplified — not aligned to column).
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        if c == '\t' {
            for _ in 0..TAB_STOP {
                out.push(' ');
            }
        } else if (c as u32) < 0x20 {
            out.push('?');
        } else {
            out.push(c);
        }
    }
    out
}
